def solve_problem(s):
    lower_count = 0
    higher_count = 0
    length = len(s)
    for c in s:
        if c.islower():
            lower_count += 1
        else:
            higher_count += 1

        if lower_count > length // 2:
            return s.lower()

    return s.lower() if lower_count == higher_count else s.upper()

def main():
    s = input()
    print(solve_problem(s))

if __name__ == "__main__":
    main()

